10	#include <vector>
11	#include <cerrno>
12	#include <sys/random.h>
13	
14	namespace preview {
15	template<class Domain> struct Id {
16	    uint64_t value{};
17	    auto operator<=>(const Id&) const = default;
18	};
19	struct Lifetime; struct Session; struct Frontend; struct Incarnation;
20	struct Output; struct Privacy; struct Rendering; struct Scene; struct Content;
21	struct Request; struct Origin; struct Clock; struct ReceiptSequence;
22	struct Binding {
23	    Id<Lifetime> lifetime; Id<Session> session; Id<Frontend> frontend;
24	    auto operator<=>(const Binding&) const = default;
25	};
26	struct Context {
27	    Id<Lifetime> lifetime; Id<Incarnation> incarnation; Id<Output> output;
28	    Id<Privacy> privacy; Id<Rendering> rendering; Id<Scene> scene; Id<Content> content;
29	    auto operator<=>(const Context&) const = default;
30	};
31	struct Job {
32	    Binding binding; Context context; Id<Request> request; Id<Origin> origin;
33	    Id<Clock> clock; uint64_t deadline{};
34	    auto operator<=>(const Job&) const = default;
35	};
36	struct Scope {
37	    Binding binding; Context context; Id<Clock> clock; uint64_t now{};
38	    bool present{true}, sourceLive{true}, locked{false}, gpuReady{true};
39	};
40	struct Token {
41	    std::array<uint8_t,16> brokerNonce{}; uint64_t sequence{};
42	    auto operator<=>(const Token&) const = default;
43	};
44	struct Packet {
45	    Job job; Token token; bool signaled{};
46	    enum class Fidelity { Client, Family } fidelity{Fidelity::Client};
47	    uint8_t coverage{1}; uint64_t expires{};
48	};
49	struct Buffer {
50	    virtual ~Buffer() = default;
51	    virtual uint64_t charge() const noexcept = 0;
52	};
53	struct Limits { size_t entries, records, items; uint64_t bytes; };
54	struct Receipt {
55	    enum class Kind { Offer, Fence, Refused, Cancelled, Released } kind;
56	    uint64_t entry; Job job; std::optional<Packet> packet;
57	    Id<ReceiptSequence> sequence;
58	};
59	struct Result {
60	    enum class Status { Admitted, Refused, Duplicate, Ignored, Backpressure, Complete, Exhausted } status{Status::Ignored};
61	    std::vector<Receipt> receipts;
62	};
63	class Broker {
64	    struct Actor { Scope scope; uint64_t cost, floor{}; bool coherent{true}; };
65	    struct Record {
66	        uint64_t entry; Job job; uint64_t bytes{};
67	        std::shared_ptr<const Buffer> buffer{};
68	        std::optional<Packet> packet{};
69	        bool cleanup{}, producerDone{}, consumerDone{true}, cancelled{}, terminal{};
70	        std::vector<Receipt> proof{};
71	    };
72	    Limits limits_;
73	    std::array<uint8_t,16> nonce_{};
74	    std::map<uint64_t,Actor> actors_;
75	    std::map<Job,Record> records_;
76	    uint64_t nextToken_{1}, nextReceipt_{1};
77	    bool tokenExhausted_{}, receiptExhausted_{};
78	    static bool positive(const Binding& b) { return b.lifetime.value && b.session.value && b.frontend.value; }
79	    static bool positive(const Context& c) { return c.lifetime.value && c.incarnation.value && c.output.value && c.privacy.value && c.rendering.value && c.scene.value && c.content.value; }
80	    static bool valid(const Scope& s) { return positive(s.binding) && positive(s.context) && s.binding.lifetime==s.context.lifetime && s.clock.value && s.now; }
81	    static bool valid(const Job& j) { return positive(j.binding) && positive(j.context) && j.binding.lifetime==j.context.lifetime && j.request.value && j.origin.value && j.clock.value && j.deadline; }
82	    static bool generations(const Context& a,const Context& b) { return a.lifetime==b.lifetime && a.incarnation==b.incarnation && a.output==b.output && a.privacy==b.privacy && a.rendering==b.rendering; }
83	    Actor* actor(uint64_t entry,const Binding& authenticated) {
84	        auto it=actors_.find(entry);
85	        return it!=actors_.end() && it->second.scope.binding==authenticated ? &it->second : nullptr;
86	    }
87	    Record* record(uint64_t entry,const Job& job) {
88	        auto it=records_.find(job);
89	        return it!=records_.end() && it->second.entry==entry ? &it->second : nullptr;
90	    }
91	    std::optional<Receipt> receipt(Receipt::Kind kind,const Record& r) {
92	        if(receiptExhausted_) return {};
93	        Receipt result{kind,r.entry,r.job,r.packet,{nextReceipt_}};
